import {defaults} from './engine.mjs';
import {strategyNames,validateCombination,entryModeNames,validateEntryMode} from './combination.mjs';
import {parameterSchema} from './parameter-schema.mjs';
import {assessWarmup} from './warmup.mjs';
import {requiredWarmupSessions} from './research-input.mjs';
import {prepareBundle} from './quality.mjs';
import {comparePortfolio} from './portfolio.mjs';

const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Number.isFinite(v)?v.toLocaleString('zh-CN',{maximumFractionDigits:2}):'—',pct=v=>Number.isFinite(v)?(v*100).toFixed(2)+'%':'—';
const keys={swing:['dailyFast','dailySlow','breakout','exitPeriod','atrPeriod','atrMult','confirmationDays','maxGap','maxExtensionATR','cooldownDays','fast','slow'],ma:['fast','slow'],macd:['macdFast','macdSlow','macdSignal'],rsi:['rsiPeriod','rsiBuy','rsiSell'],boll:['bbPeriod','bbMult']};
const financial=['capital','allocation','stop','take','commission','minCommission','stamp','handling','regulatory','transfer','slippage'];
function field(key,value){const s=parameterSchema[key];return `<label>${esc(s.label)}<input type="number" name="${key}" value="${value}" min="${s.min}" max="${s.max}" step="${s.step}" required></label>`;}
function codes(text){const a=text.trim().split(/[\s,，;；]+/).filter(Boolean);if(!a.length||a.length>30||a.some(s=>!/^\d{6}$/.test(s))||new Set(a).size!==a.length)throw Error('请输入1–30个不重复的六位代码，用空格、逗号或换行分隔。');return a;}
export function setupPortfolio({api,getConfig,notify,collect}){
 const root=$('#portfolio-body');let base={...defaults,...getConfig(),dataMode:'single'},catalog=[],result=null,activeWorker=null,epoch=0,busy=false,page=0,history=[],rejectCalculation=null;
 try{history=JSON.parse(localStorage.getItem('qingheng-portfolio-history')||'[]').filter(x=>x.reportId).slice(0,20);}catch{}
 root.innerHTML=`<form id="portfolio-form"><div class="portfolio-grid"><label class="portfolio-wide">股票池（也可只填一只，测试多策略）<textarea id="portfolio-codes" rows="2" placeholder="600188,600519,000001" required></textarea></label><label>开始日期<input name="from" type="date" value="${base.from}" required></label><label>结束日期<input name="to" type="date" value="${base.to}" required></label><label>执行周期<select name="timeframe"><option value="5m">5分钟</option><option value="15m" selected>15分钟</option><option value="1d">日线</option></select></label><label>最大同时持仓数<input name="maxHoldings" type="number" min="1" max="30" step="1" value="3" required></label><label>股票池准入<select name="scope"><option value="single-security">自选股票 · 保留ST与公司行动校验</option><option value="hs300">历史沪深300 · 需要历史成员证据</option></select></label><label>入场组合方式<select name="entryMode"><option value="all">共同确认（全部满足）</option><option value="any">任一策略满足</option></select></label><label>退出条件<select name="exitMode"><option value="trend">趋势与风控优先（含大波段时）</option><option value="any">任一所选策略发出离场信号</option></select></label></div><fieldset class="portfolio-strategies"><legend id="portfolio-entry-legend">共同确认入场（必须全部满足）</legend>${Object.entries(strategyNames).map(([k,v])=>`<label><input type="checkbox" name="strategies" value="${k}" ${['swing','macd'].includes(k)?'checked':''}>${v}</label>`).join('')}</fieldset><p id="portfolio-entry-help" class="help"></p><p class="help">默认大波段＋MACD。入场方式与退出条件分别设置；止损、止盈、ST退出始终优先。所选大波段的ATR、跳空与冷却风控也适用于任一入场。所有指标只读取已完成K线；组合效果需与基准比较。</p><details open><summary>所选策略参数</summary><div id="portfolio-params" class="portfolio-grid"></div></details><details><summary>共享资金、五项费用与滑点（可修改）</summary><div class="portfolio-grid">${financial.map(k=>field(k,base[k])).join('')}</div><label>税费口径<select name="taxMode"><option value="manual">使用当前固定费率</option><option value="historical">按历史日期替换印花税与过户费</option></select></label></details><p class="help">首次建仓预算＝当时组合净资产×总仓位上限÷最大持仓数，费用也占预算。持仓不自动再平衡，本版组合采用一次建仓与退出；单标的页保留加仓及做T。资金或名额冲突按代码顺序处理。</p><div class="portfolio-actions"><button id="portfolio-run" class="button primary">运行组合并比较</button><button id="portfolio-cancel" type="button" class="button secondary" hidden>取消计算</button><button id="portfolio-copy" type="button" class="button secondary">复制单标的参数与费用</button><button id="portfolio-demo" type="button" class="button secondary">试用合成组合</button><button id="portfolio-collect" type="button" class="text-button">批量采集此股票池与区间</button><button id="portfolio-refresh" type="button" class="text-button">刷新本地快照</button></div></form><p id="portfolio-status" role="status" aria-live="polite"></p><div id="portfolio-inputs"></div><div class="portfolio-actions"><button id="portfolio-export" class="button secondary" disabled>下载组合报告JSON</button><button id="portfolio-csv" class="button secondary" disabled>下载交易明细CSV</button></div><div id="portfolio-result"></div><details class="portfolio-history"><summary>已保存的组合报告</summary><div id="portfolio-history"></div></details>`;
 const form=$('#portfolio-form');form.elements.timeframe.value=base.timeframe;
 function updateEntryMode(){const any=form.elements.entryMode.value==='any';$('#portfolio-entry-legend').textContent=any?'任一策略入场（至少一个满足）':'共同确认入场（必须全部满足）';$('#portfolio-entry-help').textContent=any?'任一勾选策略满足即可入场，不要求其他策略同时确认；可能增加交易频率和费用。':'全部勾选策略同时满足才入场。趋势与超卖策略可能相互冲突，使交易很少。';}
 updateEntryMode();
 function strategies(){return [...form.querySelectorAll('[name=strategies]:checked')].map(x=>x.value);}
 function read(){const c={...base,strategies:strategies(),strategy:strategies()[0]??'swing',dataMode:'single',management:'base'};for(const [k,v]of new FormData(form))if(k!=='strategies')c[k]=typeof defaults[k]==='number'||k==='maxHoldings'?Number(v):v;return c;}
 function parameters(){for(const input of $('#portfolio-params').querySelectorAll('input'))base[input.name]=Number(input.value);const selected=[...new Set(strategies().flatMap(k=>keys[k]))];$('#portfolio-params').innerHTML=selected.map(k=>field(k,base[k])).join('');}
 function dirty(){if(busy)cancel();$('#portfolio-export').disabled=true;$('#portfolio-csv').disabled=true;$('#portfolio-status').textContent=result?'设置已更改；下方仍是上次结果，请重新运行。':'从本地已采集快照选取行情；研究日期可以自定义。';}
 function cancel(){epoch++;rejectCalculation?.(Error('计算已取消。'));rejectCalculation=null;activeWorker?.terminate();activeWorker=null;busy=false;$('#portfolio-run').disabled=false;$('#portfolio-cancel').hidden=true;$('#portfolio-status').textContent='已取消；行情快照未改变。';}
 form.addEventListener('input',dirty);form.addEventListener('change',e=>{if(e.target.name==='strategies')parameters();if(e.target.name==='entryMode')updateEntryMode();dirty();});
 $('#portfolio-copy').onclick=()=>{base={...defaults,...getConfig(),dataMode:'single'};for(const [k,v]of Object.entries(base)){const input=form.elements.namedItem(k);if(input&&k!=='strategies')input.value=v;}parameters();dirty();notify('已复制策略参数、研究日期、资金与五项费用；组合股票池和所选策略保留。');};
 $('#portfolio-cancel').onclick=cancel;
 function download(name,text,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
 $('#portfolio-export').onclick=()=>download('组合回测-'+result.period.from+'-'+result.period.to+'.json',JSON.stringify(result,null,2));
 $('#portfolio-csv').onclick=()=>{const headers=['证券代码','成交时间','确认时间','方向','数量','价格','金额','费用','平仓盈亏','触发原因'];const quote=x=>'"'+String(x??'').replaceAll('"','""')+'"';download('组合交易明细.csv','\uFEFF'+[headers,...result.trades.map(t=>[t.symbol,t.date,t.confirmationTime,t.side,t.quantity,t.price,t.amount,t.fee,t.pnl,t.reason])].map(row=>row.map(quote).join(',')).join('\r\n'),'text/csv;charset=utf-8');};
 async function refresh(){let cursor=null;const seen=new Set(),entries=new Map();do{const v=await api('/api/data/catalog'+(cursor?'?cursor='+encodeURIComponent(cursor):''));for(const x of v.entries)entries.set(x.id,x);cursor=v.truncated?v.cursor:null;if(cursor&&seen.has(cursor))throw Error('快照分页游标重复');seen.add(cursor);}while(cursor);catalog=[...entries.values()];return catalog;}
 $('#portfolio-refresh').onclick=async()=>{try{await refresh();$('#portfolio-status').textContent=`找到 ${catalog.length} 个行情快照；运行时自动匹配代码、日期和预热，必要时合并已有分段。`;}catch(e){$('#portfolio-status').textContent=e.message;}};
 $('#portfolio-collect').onclick=()=>{try{collect(codes($('#portfolio-codes').value),read());}catch(e){notify(e.message);}};
 async function resolve(symbol,c,current){
  const sufficient=b=>{prepareBundle(b,{scope:c.scope});return assessWarmup(b,c,c.strategies.map(strategy=>({...c,strategy}))).sufficient;};
  const choices=catalog.filter(x=>x.symbol===symbol&&x.report?.requested?.from<=c.from&&x.report?.requested?.to>=c.to).sort((a,b)=>Number(!!b.minuteRepair)-Number(!!a.minuteRepair)||Number(!!b.corporateCorrections)-Number(!!a.corporateCorrections)||b.syncedAt.localeCompare(a.syncedAt));
  let failure;
  for(const x of choices){try{const b=await api('/api/data/bundle?id='+x.id);current();if(sufficient(b))return {symbol,snapshotId:x.id,data:b};}catch(e){current();failure=e;}}
  const warmupSessions=requiredWarmupSessions(c),lookback=new Date(Date.parse(c.from+'T00:00:00Z')-Math.max(365,warmupSessions*4)*86400000).toISOString().slice(0,10);
  const parts=catalog.filter(x=>x.symbol===symbol&&x.timeframe==='5m'&&x.report?.requested?.to>=lookback&&x.report?.requested?.from<=c.to);
  if(!parts.length)throw Error(symbol+' 无覆盖区间的本地行情；请批量采集此股票池与区间。'+(failure?' '+failure.message:''));
  const x=await api('/api/data/assemble',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({symbol,from:c.from,to:c.to,warmupSessions,snapshots:parts.map(x=>x.id)})});current();
  const b=await api('/api/data/bundle?id='+x.id);current();if(!sufficient(b))throw Error(symbol+' 预热不足；请补采开始日前历史。');return {symbol,snapshotId:x.id,data:b};
 }
 function chart(r){const mode=entryModeNames[r.config.entryMode??'all'],points=r.dailyCurve,baseCurve=new Map(r.baselineCurve.map(p=>[p.date,p.nav])),w=900,h=230,ys=points.flatMap(p=>[p.nav,baseCurve.get(p.date)??1]),lo=Math.min(...ys,1),hi=Math.max(...ys,1),x=i=>40+i*820/Math.max(1,points.length-1),y=v=>195-(v-lo)*165/Math.max(.01,hi-lo);
  const path=fn=>points.map((p,i)=>(i?'L':'M')+x(i).toFixed(1)+','+y(fn(p)).toFixed(1)).join(' ');
  return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="组合与首个策略基准的日末净值"><line x1="40" y1="${y(1)}" x2="860" y2="${y(1)}" stroke="#dce4eb"/><path d="${path(p=>baseCurve.get(p.date)??1)}" fill="none" stroke="#9cabb7" stroke-width="2"/><path d="${path(p=>p.nav)}" fill="none" stroke="#238b80" stroke-width="2.5"/><text x="40" y="222" font-size="12">${r.period.from}</text><text x="770" y="222" font-size="12">${r.period.to}</text><text x="40" y="18" font-size="12">${hi.toFixed(3)}</text><text x="40" y="192" font-size="12">${lo.toFixed(3)}</text></svg><p class="help">绿色：${esc(mode)}组合；灰色：首个策略、同股票池共享资金基准。均已扣五项费用及滑点。只比较用户指定方案，不按结果自动挑选股票或策略。</p>`;
 }
 function tradePage(){const rows=[...result.trades].reverse(),pages=Math.max(1,Math.ceil(rows.length/10));page=Math.max(0,Math.min(page,pages-1));$('#portfolio-trades').innerHTML=`<div class="table-wrap"><table><thead><tr><th>代码</th><th>成交时间</th><th>方向</th><th>成交价</th><th>数量</th><th>费用/元</th><th>平仓盈亏/元</th><th>原因</th></tr></thead><tbody>${rows.slice(page*10,page*10+10).map(t=>`<tr><td>${t.symbol}</td><td>${t.date}</td><td>${t.side}</td><td>${num(t.price)}</td><td>${num(t.quantity)}</td><td>${num(t.fee)}</td><td>${num(t.pnl)}</td><td>${esc(t.reason)}</td></tr>`).join('')}</tbody></table></div><div class="portfolio-actions"><span>${rows.length}笔成交 · ${page+1}/${pages}页</span><button type="button" data-page="0">首页</button><button type="button" data-page="${page-1}" ${page===0?'disabled':''}>上一页</button><button type="button" data-page="${page+1}" ${page===pages-1?'disabled':''}>下一页</button><button type="button" data-page="${pages-1}">末页</button><form id="portfolio-page-form"><label>跳至<input id="portfolio-page-number" type="number" min="1" max="${pages}" value="${page+1}" required>页</label><button>跳转</button></form></div><p class="help">平仓盈亏只在该股整段持仓及公司权益结算后统计；未平仓收益见收益贡献。期末不强平。</p>`;$('#portfolio-trades').querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=Number(b.dataset.page);tradePage();});$('#portfolio-page-form').onsubmit=e=>{e.preventDefault();page=Number($('#portfolio-page-number').value)-1;tradePage();};}
 function render(r){$('#portfolio-inputs').innerHTML='<p class="help">入场方式：'+esc(entryModeNames[r.config.entryMode??'all'])+' · 固定输入：'+r.inputs.map(x=>esc(x.symbol)+' · '+(x.snapshotId?esc(x.snapshotId.slice(0,12)):'合成演示')).join('；')+'</p>';
  $('#portfolio-result').innerHTML=`<div class="portfolio-metrics">${[['组合收益',pct(r.metrics.total)],['最大回撤',pct(r.metrics.maxdd)],['期末资产/元',num(r.metrics.equity)],['剩余现金/元',num(r.metrics.cash)],['费用/元',num(r.metrics.fees)],['完整平仓',r.metrics.closedTrades]].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><section class="portfolio-section"><h2>组合净值与基准</h2>${chart(r)}</section><section class="portfolio-section"><h2>同区间方案比较</h2><div class="table-wrap"><table><thead><tr><th>方案</th><th>收益率</th><th>最大回撤</th><th>完整平仓</th><th>胜率</th><th>费用/元</th></tr></thead><tbody>${r.comparison.rows.map(x=>`<tr><td>${esc(x.name)}</td><td>${pct(x.metrics.total)}</td><td>${pct(x.metrics.maxdd)}</td><td>${x.metrics.closedTrades}</td><td>${pct(x.metrics.winrate)}</td><td>${num(x.metrics.fees)}</td></tr>`).join('')}</tbody></table></div><p class="help">单标的基准各自使用同样初始资金独立运行，仅用于比较；这些账户没有相加或平均为组合收益。反复根据本区间调整方案会产生过拟合，应另外保留未参与调整的验证区间。</p></section><section class="portfolio-section"><h2>逐股持仓与收益贡献</h2><div class="table-wrap"><table><thead><tr><th>代码</th><th>可交易股数</th><th>锁定股数</th><th>应收股息/元</th><th>已平仓收益/元</th><th>未完成持仓盈亏/元</th><th>总贡献/元</th></tr></thead><tbody>${r.contributions.map(s=>`<tr><td>${s.symbol}</td><td>${num(s.quantity)}</td><td>${num(s.lockedQuantity)}</td><td>${num(s.receivable)}</td><td>${num(s.realized)}</td><td>${num(s.unrealized)}</td><td>${num(s.pnl)}</td></tr>`).join('')}</tbody></table></div></section><section class="portfolio-section"><h2>组合交易明细</h2><div id="portfolio-trades"></div></section><section class="portfolio-section"><h2>账户核验与提示</h2><p>收益贡献与期末资产已核对 · 最多实际占用 ${r.metrics.maxHeld} 个名额 · 未成交订单 ${r.orderAttempts.filter(o=>o.status==='unfilled').length} 笔</p><ul>${r.warnings.map(w=>'<li>'+esc(w)+'</li>').join('')}</ul></section>`;page=0;tradePage();$('#portfolio-export').disabled=false;$('#portfolio-csv').disabled=false;
 }
 function renderHistory(){$('#portfolio-history').innerHTML=history.length?history.map(x=>`<p>${esc(x.at.slice(0,19))} · ${esc(x.symbols.join('、'))} · ${esc(x.from)}—${esc(x.to)} · ${esc(entryModeNames[x.entryMode??'all'])} · 收益${pct(x.total)} <button type="button" data-report="${x.reportId}">查看报告</button></p>`).join(''):'尚无已保存的组合报告。';$('#portfolio-history').querySelectorAll('[data-report]').forEach(b=>b.onclick=async()=>{try{const v=await api('/api/portfolio/reports/'+b.dataset.report);result=v.report;render(result);$('#portfolio-status').textContent='查看已保存报告；当前表单设置未覆盖，下载内容仍为该报告。';}catch(e){notify(e.message);}});}
 async function execute(demoInputs=null){const id=++epoch,current=()=>{if(id!==epoch)throw Error('设置改变或计算已取消。');};busy=true;$('#portfolio-run').disabled=true;$('#portfolio-cancel').hidden=false;$('#portfolio-export').disabled=true;$('#portfolio-csv').disabled=true;
  try{const c=read();validateCombination(c.strategies);validateEntryMode(c.entryMode);const list=demoInputs?demoInputs.map(x=>x.symbol):codes($('#portfolio-codes').value);let inputs=demoInputs??[];
   if(!demoInputs){$('#portfolio-status').textContent='正在匹配本地快照并核验完整性…';await refresh();current();for(const symbol of list){$('#portfolio-status').textContent='正在载入 '+symbol+'；只读取本地快照，不请求行情供应商…';inputs.push(await resolve(symbol,c,current));}}
   if(demoInputs)c.dataMode='demo';current();$('#portfolio-status').textContent='正在计算共享资金组合、单策略和逐股基准…';
   const r=await new Promise((resolve,reject)=>{rejectCalculation=reject;try{activeWorker=new Worker('./portfolio-worker.js',{type:'module'});activeWorker.onmessage=({data:v})=>v.error?reject(Error(v.error)):resolve(v.result);activeWorker.onerror=()=>reject(Error('组合计算进程加载失败，请刷新后重试。'));activeWorker.postMessage({id,inputs,config:c});}catch{Promise.resolve().then(()=>comparePortfolio(inputs,c)).then(resolve,reject);}});current();result=r;render(r);$('#portfolio-status').textContent=`组合计算完成：${inputs.length}只股票，${c.strategies.length}个策略，${entryModeNames[r.config.entryMode]}，共享¥${num(c.capital)}；收益 ${pct(r.metrics.total)}。`;
   try{const saved=await api('/api/portfolio/reports',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({report:r})});current();history.unshift({reportId:saved.id,at:new Date().toISOString(),symbols:list,from:c.from,to:c.to,entryMode:r.config.entryMode,total:r.metrics.total});history=history.slice(0,20);try{localStorage.setItem('qingheng-portfolio-history',JSON.stringify(history));}catch{}renderHistory();$('#portfolio-status').textContent+=' 报告已保存，编号 '+saved.id.slice(0,12)+'。';}catch(e){current();$('#portfolio-status').textContent+=' 报告保存失败：'+e.message+'；可下载JSON保留。';}
  }catch(e){if(id===epoch)$('#portfolio-status').textContent=e.message;}finally{if(id===epoch){busy=false;rejectCalculation=null;activeWorker?.terminate();activeWorker=null;$('#portfolio-run').disabled=false;$('#portfolio-cancel').hidden=true;}}
 }
 form.onsubmit=e=>{e.preventDefault();execute();};
 $('#portfolio-demo').onclick=async()=>{const {demoMinuteData}=await import('./data.mjs');const a=demoMinuteData(),b=a.map((r,i)=>({...r,open:r.open*(.7+Math.sin(i/900)*.015),high:r.high*(.7+Math.sin(i/900)*.015),low:r.low*(.7+Math.sin(i/900)*.015),close:r.close*(.7+Math.sin(i/900)*.015),prev_close:r.prev_close*(.7+Math.sin(i/900)*.015)}));$('#portfolio-status').textContent='使用两只合成演示；不会采集或替换真实股票行情。';execute([{symbol:'000001',data:a},{symbol:'600519',data:b}]);};
 parameters();renderHistory();return {refresh};
}
